# -*- coding: utf-8 -*-
"""MANAPRINT — HAKARI · 6 boules (création 2KEA) · maquette CANVA de Maeva (27/11/2026,
« hakari_canva_20_A4 »). Reprise TELLE QUELLE : 20 cartons / feuille A4 PORTRAIT
(4 colonnes x 5 rangées). Chaque carton : cadre arrondi, « N° », le titre HAKARI, le COCOTIER
et les herbes (dessin de la maquette posé en pochoir : en couleur, MANAPRINT le repeint, les
chiffres restent noirs), les 5 cases et le cercle central. Dessin rangé une fois par document.
RÈGLE (inchangée) — SIX numéros :
   B 1-15 : deux cases à gauche (le plus petit en haut) · N 31-45 : deux cases à droite (le plus
   petit en haut) · I 16-30 : la case du bas · O 61-75 : le cercle au centre du cocotier.
   Crieur : 1-45 et 61-75. Chiffres de la maquette (serif gras, 30 pt), noirs.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = A4
COLS, RANGS = 4, 5
CARTES_PAGE = COLS * RANGS                # 20
CELL_W, CELL_H = 148.8189, 168.3780
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Times-Bold", 30
# (centre x, ligne de base) : B haut, B bas, N haut, N bas, I (bas), O (cercle)
POS = {"B1": (28.06299, 110.289), "B2": (28.06299, 51.89528),
       "N1": (120.7559, 110.289), "N2": (120.7559, 51.89528),
       "I": (74.40945, 12.21024), "O": (74.40945, 70.03701)}
PLAGE_TXT = {"B1": "1-15", "B2": "1-15", "N1": "31-45", "N2": "31-45", "I": "16-30", "O": "61-75"}
_IMGS = [(16.46951, 8.220472, 117.5807, 147.9685), (4.535433, 9.588137, 25.51181, 22.15989),
         (0, 8.066416, 23.24409, 21.98083)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        b = sorted(rng.sample(range(1, 16), 2)); n = sorted(rng.sample(range(31, 46), 2))
        t = {"B1": b[0], "B2": b[1], "N1": n[0], "N2": n[1],
             "I": rng.randint(16, 30), "O": rng.randint(61, 75)}
        k = tuple(sorted(t.items()))
        if k not in _DEJA:
            break
    _DEJA.add(tuple(sorted(t.items())))
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_hakari_modele", False):
        return
    import base64
    d = _DESSIN
    for k, v in (("{TB}", "Times-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("HAKARI_CANVA", 0, 0, CELL_W, CELL_H)
    morceaux = d.replace("@IMG0@", "\x00").replace("@IMG1@", "\x01").replace("@IMG2@", "\x02")
    c._code.append("q")
    tampon = ""
    for ch in morceaux:
        if ch in "\x00\x01\x02":
            c._code.append(tampon); tampon = ""
            i = ord(ch); x, y, w, h = _IMGS[i]
            _masque.poser(c, "HAKARI_IMG_%d" % i, base64.b64decode(_PNG[i]), x, y, w, h)
        else:
            tampon += ch
    c._code.append(tampon + "\nQ")
    c.endForm()
    c._hakari_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("HAKARI_CANVA")
    _txt(c, "N° %06d" % serie, 8.503937, 149.6693, "Helvetica", 6.5, colors.Color(.1, .1, .1))
    for k, (x, y) in POS.items():
        _txt(c, str(nums[k]), x, y - 2.5, POLICE_NUM, T_NUM, col, centre=True)
        _txt(c, PLAGE_TXT[k], x, y + 21.5, "Helvetica-Bold", 5.2, NOIR, centre=True)   # la plage (27/11)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("HAKARI · 6 boules")
    rng = random.Random(int(serie_start) * 100003 + 1127)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


